import TypeWriterEffect from 'react-typewriter-effect';
import { useState } from 'react';

const TypeWriter = () => {
    const [count, setCount] = useState(1);

    useEffect(() => {
      // document.title = `You clicked ${count} times`;
      console.log("Count: " + count);
      setCount(1);
    }, [count]);

    return (
        <TypeWriterEffect
            textStyle={{
            fontFamily: 'Red Hat Display',
            color: '#FFFF',
            fontWeight: 400,
            fontSize: '1.5em',
            }}
            startDelay={2000}
            cursorColor="#FFFF"
            multiText={[ 
            'HTML5',
            'CSS3',
            'JavaScript',
            'SASS',
            'Python',
            'React',
            'BootStrap',
            'Visual Studios Code',
            'Git and GitHub',
            'Figma',
            'Programming Techniques',
            'Agile Methodology',
            'Linux OS',
            'Windows OS',
            'Desktop Computer Hardware'
            ]}
            multiTextDelay={1100}
            typeSpeed={50}
        />
    );
}

export default TypeWriter;
